<?php

# @autogenerated
declare(strict_types=1);
namespace Civi\Lughauth\Features\Document\TemplateVersion\Application\Usecase\Update;

use Psr\EventDispatcher\EventDispatcherInterface;

use Throwable;

use Civi\Lughauth\Shared\Security\Allow;
use Civi\Lughauth\Shared\Exception\UnauthorizedException;
use Civi\Lughauth\Shared\Exception\NotFoundException;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersionRef;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\TemplateVersionAttributes;
use Civi\Lughauth\Features\Document\TemplateVersion\Application\Service\Visibility\TemplateVersionVisibilityService;
use Civi\Lughauth\Features\Document\TemplateVersion\Domain\Gateway\TemplateVersionWriteGateway;
use Civi\Lughauth\Shared\Observability\LoggerAwareTrait;
use Civi\Lughauth\Shared\Observability\TracerAwareTrait;

class TemplateVersionUpdateUsecase
{
  use LoggerAwareTrait;
  use TracerAwareTrait;

  public function __construct(
    private readonly EventDispatcherInterface $dispatcher,    private readonly TemplateVersionVisibilityService $visibility,
    private readonly TemplateVersionWriteGateway $writer,
  ) {
  }

  public function allowUpdate(?TemplateVersionRef $ref = null): Allow
  {
    $this->logDebug("Check allow update usecase for Template version");
    $span = $this->startSpan("Check allow update usecase for Template version");
    try {
      $result = $this->dispatcher->dispatch(new TemplateVersionUpdateAllowDecision(Allow::allowed('update', 'Allowed to update by default')));
      return $result->getAllow();
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function fixedFields(?TemplateVersionRef $ref = null): array
  {
    $this->logDebug("Check fixed fields for update usecase for Template version");
    $span = $this->startSpan("Check fixed fields for update usecase for Template version");
    try {
      return $this->visibility->fieldsToFix($ref);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
  public function update(string $uid, TemplateVersionUpdateParams $params): TemplateVersionUpdateResult
  {
    $this->logDebug("Run update usecase for Template version");
    $span = $this->startSpan("Run update usecase for Template version");
    try {
      $ref = new TemplateVersionRef($uid);
      $allow = $this->allowUpdate($ref);
      if( !$allow->allowed ) {
        throw new UnauthorizedException($allow->reason ?? 'Not allowed to update Template version');
      }
      if (!$original = $this->visibility->retrieveVisibleForUpdate($ref)) {
        throw new NotFoundException($uid);
      }
      $this->dispatcher->dispatch(new TemplateVersionUpdateCheck($params, $original));
      $enriched = $this->dispatcher->dispatch( new TemplateVersionUpdateEnrich($params, $original, $params->toAttributes() ) );
      $attributes = $enriched->getResult();      $input = $this->visibility->copyWithFixed( $attributes );
      $modified = $original->update( $input );
      $result= $this->writer->update($original, $modified);
      $output = $this->visibility->copyWithHidden( $this->visibility->prepareVisibleData( $result ) );
      return new TemplateVersionUpdateResult($output);
    } catch(Throwable $ex) {
      $span->recordException($ex);
      throw $ex;
    } finally {
      $span->end();
    }
  }
}